<span class="line"><span style="color:#C792EA;">const</span><span style="color:#BABED8;"> utterance </span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;"> new</span><span style="color:#82AAFF;"> SpeechSynthesisUtterance</span><span style="color:#BABED8;">(text)</span><span style="color:#89DDFF;">;</span></span>
